{
  "cases": [
    {
      "i": 18825,
      "title": "User provisioning sync halted in production (ANZ region)",
      "description": "We are experiencing a critical issue with the SSO Integration Module in our production environment. Since approximately 08:00 UTC, the user provisioning sync has been completely stuck. No new users are being created in the target directory, and updates to existing profiles are not propagating. This is affecting 1,455 users who cannot access services. We have verified that credentials are valid and network connectivity is stable. Please investigate immediately."
    },
    {
      "i": 18826,
      "title": "MFA prompts missing and unexpected session expirations",
      "description": "Users in our US-West production environment are reporting two distinct issues with the SSO Integration Module. First, Multi-Factor Authentication (MFA) prompts are failing to appear during login for some users, allowing single-factor access. Second, active sessions are expiring much earlier than the configured timeout, forcing users to re-authenticate frequently. This impacts 668 users and is causing significant disruption to workflow. Please advise."
    },
    {
      "i": 18827,
      "title": "Incorrect tax calculations and invoice discrepancies in dev",
      "description": "In our development environment (US-West), we are seeing errors in the Payment Gateway v2. Specifically, the tax amount calculated on transactions is incorrect, which in turn causes the generated invoices to reflect the wrong totals. It is unclear if the issue lies with the tax calculation engine itself or the downstream settlement service processing the invoice data. This is currently affecting 2 users during testing but blocks our integration verification."
    },
    {
      "i": 18828,
      "title": "Missing consent records and audit log gaps in Analytics Dashboard",
      "description": "We have noticed that the Analytics Dashboard in our production ME region is displaying incomplete data. Specifically, certain user consent records appear to be missing from the view, and there are gaps in the audit logs where entries should exist. This appears to be a data visibility issue within the dashboard itself. We have not observed any errors on the client side, but the missing information is raising compliance concerns."
    },
    {
      "i": 18829,
      "title": "Refund Manager returning HTTP 500 and rate limit errors",
      "description": "Critical outage in production (ME). The Refund Manager is failing to process requests. We are receiving HTTP 500 errors on a large volume of refund attempts, alongside 'rate limit exceeded' responses. This is blocking 10,620 users from receiving refunds. The service seems to be overwhelmed or misconfigured. Please prioritize this as it is a major business impact."
    },
    {
      "i": 18830,
      "title": "Incorrect currency conversion leading to overcharges in sandbox",
      "description": "In the sandbox environment (US-West), the Fee Analyzer is producing incorrect currency conversion rates, resulting in overcharges for transactions involving multiple currencies. We suspect this might be related to how the Tax Jurisdiction Resolver is applying rules during the conversion process, but it's hard to tell which component is at fault. The fees displayed do not match the expected amounts. This affects 526 test users."
    },
    {
      "i": 18831,
      "title": "Missing consent records in Billing Engine (Staging)",
      "description": "We are seeing missing consent records in the Billing Engine in our US-East staging environment. Based on our monitoring, we think it's because of resource exhaustion on the server handling these requests. The system seems to be dropping these specific records under load. This is definitely a resource issue on our side or the environment's side. Please help confirm if this is related to memory or CPU limits."
    },
    {
      "i": 18832,
      "title": "Webhook retries exhausted and rate limits hit in Role Manager",
      "description": "In our LATAM staging environment, the Role Manager is hitting rate limits, causing webhook retries to exhaust. As a result, role changes are not being propagated to downstream systems. We have observed that the retry mechanism stops after a few attempts, leaving 382 users with incorrect permissions. We need help adjusting the rate limits or understanding why the webhooks are failing repeatedly."
    },
    {
      "i": 18833,
      "title": "Refunds and subscription issues in Payment Gateway",
      "description": "Some users in the ME production region are complaining about refunds not showing up. Also, a few people said they got charged twice for their subscription and were overcharged. It's been happening lately. We don't have exact numbers yet but it looks like a lot of people are affected. Please check."
    },
    {
      "i": 18834,
      "title": "Chat Widget not scaling up",
      "description": "The Chat Widget in US-East production isn't autoscaling. We see a few users (4) having issues. No errors visible on our end. Please look into why the capacity isn't increasing."
    },
    {
      "i": 18835,
      "title": "Subscription renewal failures and currency conversion errors",
      "description": "In our US-West production environment, users with international subscriptions are facing two issues with the Payment Gateway v2. First, automatic subscription renewals are failing for a subset of users. Second, when manual payments are attempted, the currency conversion appears to be incorrect, leading to confusion about the final charge amount. No users have been impacted severely yet, but the logic error is persistent."
    },
    {
      "i": 18836,
      "title": "API returning empty responses and HTTP 429s in Analytics Dashboard",
      "description": "We are experiencing issues with the Analytics Dashboard API in the EU-West production region. The API occasionally returns empty responses instead of data, followed by HTTP 429 (Too Many Requests) errors. This seems to happen when multiple queries are run in quick succession. Currently, this is affecting 5 users with minor impact on internal reporting."
    },
    {
      "i": 18837,
      "title": "Subscriptions failing to renew in Payment Gateway v2 (Staging)",
      "description": "Critical issue in our US-West staging environment. The Payment Gateway v2 is failing to renew subscriptions for a large batch of test accounts. Approximately 3,109 users are stuck in an inactive state. The renewal job seems to complete without errors, but the status is not updated to 'Active'. This blocks our release testing. Please investigate the subscription lifecycle logic."
    },
    {
      "i": 18838,
      "title": "Missing entries and gaps in audit logs within Fee Analyzer",
      "description": "In the LATAM development environment, the Fee Analyzer's audit logs are incomplete. We have detected missing entries and gaps in the log sequence, particularly during high-volume transaction tests. This makes it difficult to trace fee calculations for compliance purposes. 469 users are involved in these test scenarios. We need to ensure that every transaction event is captured in the audit trail."
    },
    {
      "i": 18839,
      "title": "Cross-tenant data leakage and unexpected permission denials in SSO",
      "description": "We have a critical security issue in our US-East development environment with the SSO Integration Module. Users are seeing data from the wrong tenant, and simultaneously, some users are receiving 'Permission Denied' errors unexpectedly when accessing their own resources. This affects 25,030 users and poses a severe data isolation risk. Please treat this as a priority incident."
    }
  ]
